<div class="page-heading"><div><span class="eyebrow gold-eyebrow">CONTENT MANAGEMENT</span><h1>Manage events</h1><p class="muted">Create, update, and safely remove campus events.</p></div><a class="button button-dark" data-view="admin-event-form" data-route="true" href="index.php?view=admin-event-form">Create event <span>+</span></a></div>
<form class="toolbar" method="get" action="index.php"><input type="hidden" name="view" value="admin-events"><div class="search-box"><span>Search</span><input name="q" type="search" value="<?= e($_GET['q'] ?? '') ?>" placeholder="Search events..." aria-label="Search events"></div><select name="category" aria-label="Filter event category"><option value="">All categories</option><?php foreach (['Academic', 'Creative', 'Social', 'Sports'] as $category): ?><option value="<?= e($category) ?>" <?= strtolower((string) ($_GET['category'] ?? '')) === strtolower($category) ? 'selected' : '' ?>><?= e($category) ?></option><?php endforeach; ?></select><button class="button button-outline" type="submit">Search</button></form>
